<p class="novel-p">The Tokyo evening was wet with spring rain. Neon signs blurred on the road below the pedestrian bridge. Cars hissed past. Yono walked with a plastic bag in one hand, loaded with instant ramen, two energy drinks, and a cream bun he had been saving money for since Tuesday.</p>
