<p class="novel-p">&quot;You have a very specific face you make when something is real and you haven&#x27;t finished being annoyed about it yet.&quot; Lyra came to stand beside her at the ward edge, hands in her jacket pockets, looking at the forest. &quot;I&#x27;ve updated my notes on it.&quot;</p>
