<p class="novel-p">He will think about those ten seconds for years afterward. He will not always be sure he did the right thing. The order existed for reasons. The gate was closed for reasons. Orders with reasons are the kind that are hardest to break because you understand why they are there and breaking them feels like breaking more than the order.</p>
