<p class="novel-p"><strong>Route LIRI ending:</strong> The ribbon is still on her wrist. The ward is still running. Her father has not come back. He will not come back and she knows this and it sits the way Yono told her it would: like grief that has found its shape. Something she carries rather than something that carries her.</p>
